import {CITIES,LANGUAGES,canonicalStatus} from './domain.mjs';
import {esc,btn,workLink,directions} from './ui.mjs';
const kk={
 'Другой город':'Басқа қала','Русский':'Орысша','Русский и қазақша':'Орысша және қазақша','SNEG использует ответы для отбора креаторов и связи в Telegram.':'SNEG жауаптарды креаторларды іріктеу және Telegram арқылы байланысу үшін пайдаланады.',
 'Анкета креатора':'Креатор анкетасы','Условия сотрудничества':'Ынтымақтастық шарттары','О вас':'Өзіңіз туралы','Работы':'Жұмыстар','Имя':'Атыңыз','Как к вам обращаться':'Сізді қалай атаймыз?','Город':'Қала','Выберите город':'Қаланы таңдаңыз','Язык роликов':'Видео тілі','Формат сотрудничества':'Ынтымақтастық форматы','Снимать для бренда':'Брендке видео түсіру','Размер блога не важен':'Блог көлемі маңызды емес','Публиковать у себя':'Өз парақшаңызда жариялау','Добавлю статистику просмотров':'Қаралым статистикасын қосамын','Далее':'Келесі','Назад':'Артқа','Ссылки на работы':'Жұмыс сілтемелері','До трёх ссылок, каждая с новой строки':'Үш сілтемеге дейін, әрқайсысы жаңа жолда','Reels, TikTok или видео с открытым доступом.':'Reels, TikTok немесе ашық видео.','Опыт':'Тәжірибе','Выберите опыт':'Тәжірибеңізді таңдаңыз','Снимал(а) для брендов':'Брендтерге видео түсірдім','Снимаю для своего блога':'Өз блогыма видео түсіремін','Первые проекты':'Алғашқы жобалар','Профиль':'Парақша','Средние просмотры':'Орташа қаралым','Подписчики':'Жазылушылар','Основная аудитория — в Казахстане':'Негізгі аудиториям Қазақстанда','Срок съёмки после получения':'Тауарды алғаннан кейінгі түсіру мерзімі','дней':'күн ішінде','Готов(а) снимать применение крупным планом':'Қолдануды жақыннан түсіруге дайынмын','Мне исполнилось 18 лет':'Мен 18 жасқа толдым','Прочитал(а) условия сотрудничества':'Ынтымақтастық шарттарын оқыдым','Согласен(на) на обработку анкеты для отбора и связи':'Іріктеу және байланыс үшін анкета деректерін өңдеуге келісемін','Политика':'Құпиялылық саясаты','Отправить анкету':'Анкетаны жіберу','Сохранить изменения':'Өзгерістерді сақтау','Отменить редактирование':'Өңдеуден бас тарту','Черновик сохраняется на этом устройстве на 24 часа.':'Анкета жобасы осы құрылғыда 24 сағат сақталады.','Набор закрыт':'Қабылдау жабық','Новые анкеты пока не принимаются.':'Жаңа анкеталар әзірге қабылданбайды.','На рассмотрении':'Қаралуда','Нужен ваш ответ':'Жауабыңыз қажет','Вы выбраны':'Сіз таңдалдыңыз','Товар отправлен':'Тауар жіберілді','Анкета в резерве':'Анкета резервте','Отбор завершён':'Іріктеу аяқталды','Анкета отозвана':'Анкета қайтарылды','Менеджер напишет вам в Telegram.':'Менеджер сізге Telegram арқылы жазады.','Детали отправки можно уточнить у менеджера.':'Жеткізу мәліметтерін менеджерден біле аласыз.','Менеджер задал вопрос по вашей анкете.':'Менеджер анкетаңыз бойынша сұрақ қойды.','Решение по этому набору принято.':'Осы іріктеу бойынша шешім қабылданды.','Вы отозвали анкету. Дополнительных действий не требуется.':'Анкетаңызды қайтарып алдыңыз. Қосымша әрекет қажет емес.','Решение придёт в этот бот.':'Шешім осы ботқа келеді.','Ваш ответ':'Жауабыңыз','Отправить ответ':'Жауапты жіберу','Мои работы':'Менің жұмыстарым','Изменить анкету':'Анкетаны өзгерту','Отозвать анкету':'Анкетаны қайтарып алу'
};
export function candidateScreen(s){
 const locale=s.uiLocale==='kk'?'kk':'ru',t=v=>locale==='kk'?(kk[v]||v):v,a=s.mine[0],d=s.draft,c=s.campaign;
 const languages=`<div class="language-switch" aria-label="Язык интерфейса"><button data-locale="ru" aria-pressed="${locale==='ru'}">Русский</button><button data-locale="kk" aria-pressed="${locale==='kk'}">Қазақша</button></div>`;
 if(a&&!s.editing){
  const titles={review:'На рассмотрении',clarification:'Нужен ваш ответ',approved:'Вы выбраны',sent:'Товар отправлен',reserve:'Анкета в резерве',rejected:'Отбор завершён',withdrawn:'Анкета отозвана'};
  const messages={approved:'Менеджер напишет вам в Telegram.',sent:'Детали отправки можно уточнить у менеджера.',clarification:'Менеджер задал вопрос по вашей анкете.',rejected:'Решение по этому набору принято.',withdrawn:'Вы отозвали анкету. Дополнительных действий не требуется.'};
  return `<section class="application-wrap submitted">${languages}<span class="eyebrow">${a.id}</span><h1>${t(titles[canonicalStatus(a.status)]||'На рассмотрении')}</h1><p>${t(messages[a.status]||'Решение придёт в этот бот.')}</p><div class="submitted-person"><strong>${esc(a.name)}</strong><span>${esc(a.city)} · ${LANGUAGES[a.language]}</span><div class="pills">${directions(a)}</div></div>${a.status==='clarification'?`<blockquote class="candidate-question">${esc(a.question)}</blockquote><form data-form="answer" class="stack"><label>${t('Ваш ответ')}<textarea name="answer" required minlength="2" maxlength="1500" rows="4"></textarea></label>${btn(t('Отправить ответ'),'type="submit"','primary')}<p class="form-error" role="alert"></p></form>`:''}${a.portfolio.length?`<details class="brief-note"><summary>${t('Мои работы')}</summary>${a.portfolio.map(workLink).join('')}</details>`:''}<details class="brief-note"><summary>${t('Условия сотрудничества')}</summary><p>${esc(a.briefText||c.brief)}</p></details><div class="candidate-controls">${['review','clarification','reserve'].includes(a.status)?btn(t('Изменить анкету'),'data-edit-application','secondary'):''}${['review','clarification','approved','reserve'].includes(a.status)?btn(t('Отозвать анкету'),'data-withdraw','text'):''}</div></section>`;
 }
 const options=(items,value)=>items.map(([v,label])=>`<option value="${esc(v)}" ${value===v?'selected':''}>${esc(t(label))}</option>`).join('');
 const check=(name,label)=>`<label class="check-line"><input type="checkbox" name="${name}" required ${d[name]?'checked':''}>${t(label)}</label>`;
 return `<section class="application-wrap">${languages}<h1>${t('Анкета креатора')}</h1><details class="brief-note"><summary>${t('Условия сотрудничества')}</summary><p>${esc(c.brief)}</p></details>${!c.ready||!c.active?`<div class="empty"><h2>${t('Набор закрыт')}</h2><p>${t('Новые анкеты пока не принимаются.')}</p></div>`:`<form data-form="application" class="application-form"><div class="form-progress" aria-label="${s.step}/2"><span class="${s.step===1?'active':''}">1 · ${t('О вас')}</span><span class="${s.step===2?'active':''}">2 · ${t('Работы')}</span></div>${s.step===1?`<div class="stack"><label>${t('Имя')}<input name="name" autocomplete="given-name" minlength="2" maxlength="80" value="${esc(d.name||'')}" required placeholder="${t('Как к вам обращаться')}"></label><div class="two-fields"><label>${t('Город')}<select name="city" required><option value="">${t('Выберите город')}</option>${options(CITIES.map(v=>[v,v]),d.city)}</select></label><label>${t('Язык роликов')}<select name="language">${options(Object.entries(LANGUAGES),d.language)}</select></label></div><fieldset><legend>${t('Формат сотрудничества')}</legend>${[['ugc','Снимать для бренда','Размер блога не важен'],['reach','Публиковать у себя','Добавлю статистику просмотров']].filter(([v])=>(c.directions||['ugc','reach']).includes(v)).map(([v,label,desc])=>`<label class="direction-option"><input type="checkbox" name="directions" value="${v}" ${d.directions.includes(v)?'checked':''}><span><strong>${t(label)}</strong><small>${t(desc)}</small></span></label>`).join('')}</fieldset>${btn(t('Далее'),'type="submit"','primary full')}</div>`:`<div class="stack"><label>${t('Ссылки на работы')}<textarea name="portfolio" rows="2" maxlength="3000" placeholder="${t('До трёх ссылок, каждая с новой строки')}">${esc(d.portfolio||'')}</textarea><small>${t('Reels, TikTok или видео с открытым доступом.')}</small></label><label>${t('Опыт')}<select name="experience" required><option value="">${t('Выберите опыт')}</option>${options([['brand','Снимал(а) для брендов'],['blog','Снимаю для своего блога'],['beginner','Первые проекты']],d.experience)}</select></label>${d.directions.includes('reach')?`<label>${t('Профиль')}<input type="url" name="profile" value="${esc(d.profile||'')}" required placeholder="https://…"></label><div class="two-fields"><label>${t('Средние просмотры')}<input type="number" min="0" max="1000000000" name="views" value="${esc(d.views??'')}"></label><label>${t('Подписчики')}<input type="number" min="0" max="1000000000" name="followers" value="${esc(d.followers??'')}"></label></div><label class="check-line"><input type="checkbox" name="audienceKz" ${d.audienceKz?'checked':''}>${t('Основная аудитория — в Казахстане')}</label>`:''}<label>${t('Срок съёмки после получения')}<select name="availabilityDays">${[3,7,14,30].map(n=>`<option value="${n}" ${Number(d.availabilityDays)===n?'selected':''}>${locale==='kk'?n+' '+t('дней'):'В течение '+n+' дней'}</option>`).join('')}</select></label>${check('closeup','Готов(а) снимать применение крупным планом')}${check('adult','Мне исполнилось 18 лет')}${check('terms','Прочитал(а) условия сотрудничества')}<p class="fine consent-notice">${esc(t(c.privacyText||'SNEG использует ответы для отбора креаторов и связи в Telegram.'))}</p><label class="check-line"><input type="checkbox" name="consent" required ${d.consent?'checked':''}>${t('Согласен(на) на обработку анкеты для отбора и связи')}${c.privacyUrl?' · <a href="'+esc(c.privacyUrl)+'" target="_blank" rel="noopener">'+t('Политика')+'</a>':''}</label><div class="editor-actions">${btn(t('Назад'),'type="button" data-form-back','secondary')}${btn(t(s.editing?'Сохранить изменения':'Отправить анкету'),'type="submit"','primary')}</div></div>`}<p class="form-error" role="alert"></p><p class="fine">${t('Черновик сохраняется на этом устройстве на 24 часа.')}</p></form>`}${s.editing?btn(t('Отменить редактирование'),'data-cancel-edit','text'):''}</section>`;
}
